-- Run with `supabase db push`. Create the first account in Auth, then set profiles.is_admin = true.
create extension if not exists "pgcrypto";
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, is_admin boolean not null default false, created_at timestamptz not null default now());
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select coalesce((select is_admin from public.profiles where id=auth.uid()),false) $$;
create table public.projects (id uuid primary key default gen_random_uuid(), title text not null, slug text not null unique, short_description text not null, full_description text, thumbnail_url text, categories text[] not null default '{}', technologies text[] not null default '{}', github_url text, live_url text, project_date date, featured boolean not null default false, published boolean not null default false, display_order integer not null default 0, problem text, solution text, how_it_works text, key_features text[] not null default '{}', contribution text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.project_images (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, storage_path text not null, alt_text text, display_order integer not null default 0, created_at timestamptz not null default now());
create table public.skills (id uuid primary key default gen_random_uuid(), name text not null, category text not null, description text, icon text, display_order integer not null default 0, published boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.site_content (key text primary key, content jsonb not null default '{}', published boolean not null default true, updated_at timestamptz not null default now());
create table public.resumes (id uuid primary key default gen_random_uuid(), storage_path text not null, published boolean not null default false, created_at timestamptz not null default now());
create table public.contact_submissions (id uuid primary key default gen_random_uuid(), name text not null check (char_length(name)<=160), email text not null check (char_length(email)<=320), message text not null check (char_length(message)<=5000), status text not null default 'new' check (status in ('new','read','archived')), created_at timestamptz not null default now());
create table public.site_settings (key text primary key, value text not null, updated_at timestamptz not null default now());
create table public.social_links (id uuid primary key default gen_random_uuid(), label text not null, url text not null, icon text, display_order integer not null default 0, published boolean not null default true);
create index projects_public_idx on public.projects(published,featured,display_order); create index skills_public_idx on public.skills(published,display_order); create index contacts_created_idx on public.contact_submissions(created_at desc);
alter table public.profiles enable row level security; alter table public.projects enable row level security; alter table public.project_images enable row level security; alter table public.skills enable row level security; alter table public.site_content enable row level security; alter table public.resumes enable row level security; alter table public.contact_submissions enable row level security; alter table public.site_settings enable row level security; alter table public.social_links enable row level security;
create policy "public published projects" on public.projects for select using (published or is_admin()); create policy "admins manage projects" on public.projects for all using (is_admin()) with check(is_admin());
create policy "public skills" on public.skills for select using (published or is_admin()); create policy "admins manage skills" on public.skills for all using(is_admin()) with check(is_admin());
create policy "public content" on public.site_content for select using(published or is_admin()); create policy "admins manage content" on public.site_content for all using(is_admin()) with check(is_admin());
create policy "public settings" on public.site_settings for select using(true); create policy "admins manage settings" on public.site_settings for all using(is_admin()) with check(is_admin());
create policy "public social links" on public.social_links for select using(published or is_admin()); create policy "admins manage social links" on public.social_links for all using(is_admin()) with check(is_admin());
create policy "public project images" on public.project_images for select using(exists(select 1 from projects p where p.id=project_id and (p.published or is_admin()))); create policy "admins manage images" on public.project_images for all using(is_admin()) with check(is_admin());
create policy "admins read resumes" on public.resumes for all using(is_admin()) with check(is_admin()); create policy "admins read contacts" on public.contact_submissions for select using(is_admin()); create policy "public creates contacts" on public.contact_submissions for insert with check(true); create policy "admins update contacts" on public.contact_submissions for update using(is_admin()) with check(is_admin());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values ('project-images','project-images',true,5242880,array['image/jpeg','image/png','image/webp']),('resumes','resumes',true,10485760,array['application/pdf','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document']) on conflict do nothing;
create policy "public project image files" on storage.objects for select using(bucket_id='project-images'); create policy "admins manage project image files" on storage.objects for all using(bucket_id='project-images' and is_admin()) with check(bucket_id='project-images' and is_admin()); create policy "public resume files" on storage.objects for select using(bucket_id='resumes'); create policy "admins manage resume files" on storage.objects for all using(bucket_id='resumes' and is_admin()) with check(bucket_id='resumes' and is_admin());
